S={}
T={}  # tool: N/C/D
S['AM-136']=["Set $kn=4$, so $n=\\dfrac4k$, and the rule gives $\\dfrac4k+10=82$.","Type [[y=4/x+10]] and [[y=82]].","Tap the intersection: $(0.0556,\\,82)$. Its $x$-value is $k$.","Type [[4/72]]: it returns $0.0556$, which is $\\dfrac1{18}$."]
S['AM-001']=["Type [[y=-4(x-3)^2+45]] and the line [[y=29]].","Tap the two grey dots: $(1,\\,29)$ and $(5,\\,29)$.","The height is $29$ at $t=1$ and at $t=5$, so both values count."]
S['AM-003']=["Type [[y=a(x-2)(x+6)]] (accept the slider for $a$) and plot the point [[(0,-24)]].","Slide $a$ until the curve passes through the point: $a=2$.","Type [[2(5-2)(5+6)]]: it returns $66$."]
S['AM-005']=["Type [[y=a*2^x]] (slider $a$) and plot the point [[(3,40)]].","Slide $a$ until the curve passes through the point: $a=5$.","Type [[5*2^5]]: it returns $160$."]
S['AM-006']=["Type [[y=2x^2-12x+7]].","Tap the vertex: $(3,\\,-11)$.","Check with the axis formula: type [[12/(2*2)]]; it returns $3$. The $x$-coordinate is $3$."]
S['AM-013']=["Type [[y=a*3^x]] (slider $a$) and plot the point [[(2,45)]].","Slide $a$ until the curve passes through the point: $a=5$.","Type [[5*3^4]]: it returns $405$."]
S['AM-016']=["Type [[y=-5(x-2)^2+30]] and the line [[y=10]].","Tap the two grey dots: $(0,\\,10)$ and $(4,\\,10)$.","The height is $10$ at $t=0$ and at $t=4$."]
S['AM-018']=["Put $x=1$ into the rule: $1-4+k=9$. Let $x$ stand for $k$: type [[y=1-4+x]] and [[y=9]].","Tap the intersection: $(12,\\,9)$.","So $k=12$. Check: type [[1^2-4*1+12]]; it returns $9$."]
S['AM-019']=["The zeros are $-3$ and $7$: type [[y=(x+3)(x-7)]].","Tap the vertex (the lowest point): $(2,\\,-25)$.","The minimum value of $h$ is $-25$."]
S['AM-020']=["Type [[40/2^3]]: it returns $5$, so $a=5$.","Type [[p(x)=5x^3]] and then [[p(-2)]]: it returns $-40$.","An odd power flips the sign, so $p(-2)=-p(2)=-40$."]
S['AM-026']=["Pick any positive constants, for example $a=2$ and $b=3$: type [[y=2x^2]] and [[y=3x^4]].","Tap every intersection: $(0,0)$ and two more, one on each side of the $y$-axis.","The graphs meet three times, so $f(x)=g(x)$ for three values of $x$."]
S['AM-028']=["From $N(0)=200$ we get $k=200$. Type [[y=200*2^(-a*x)]] (slider $a$).","Plot the points [[(1,50)]] and [[(2,12.5)]].","Slide $a$ until the curve passes through both points: $a=2$."]
S['AM-032']=["Inverse variation means $xy$ is constant: type [[6*15]]; it returns $90$.","Type [[y=90/x]] and tap the point with $x=10$: $(10,\\,9)$.","So $y=9$."]
S['AM-033']=["Write $z=kxy^2$. Type [[48/(3*4^2)]]: it returns $k=1$.","Type [[1*5*2^2]]: it returns $20$.","So $z=20$ when $x=5$ and $y=2$."]
S['AM-036']=["Type [[g(x)=2x-3]] and [[f(x)=x^2+1]].","Type [[f(g(2))]]: Desmos works from the inside out and returns $2$.","So $f(g(2))=2$."]
S['AM-037']=["Right $3$ and down $5$ gives $h(x)=(x-3)^2-5$. Type [[h(x)=(x-3)^2-5]].","Type [[h(7)]]: it returns $11$.","So $h(7)=11$."]
S['AM-040']=["Work from the inside out: $C(30)=30$.","Then $P(C(30))=P(30)=18$.","Type [[18]] as the final check: the input $30$ goes into $P$ unchanged."]
S['AM-041']=["Type [[y=-5x^2+20x+c]] (slider $c$) and plot the point [[(1,35)]].","Slide $c$ until the curve passes through the point: $c=20$.","Type [[-5*3^2+20*3+20]]: it returns $35$."]
S['AM-042']=["The function is undefined where the denominator is zero. Type [[y=x^2-2x-24]].","Tap the zeros: $x=-4$ and $x=6$.","Only $-4$ appears among the options."]
S['AM-046']=["Type [[y=a(x-3)(x+4)]] (slider $a$) and plot the point [[(0,-36)]].","Slide $a$ until the curve passes through the point: $a=3$.","Type [[3(6-3)(6+4)]]: it returns $90$."]
S['AM-047']=["Type [[y=3x^2-24x+10]].","Tap the vertex: $(4,\\,-86)$.","The $x$-coordinate is $4$. Check: type [[24/(2*3)]]; it returns $4$."]
S['AM-048']=["Type [[y=a*3^x]] (slider $a$) and plot the point [[(2,54)]].","Slide $a$ until the curve passes through the point: $a=6$.","Type [[6*3^4]]: it returns $486$."]
S['AM-049']=["Type [[f(x)=x^3-5x+12]].","Type [[f(-2)]]: it returns $14$.","So $f(-2)=14$."]
S['AM-060']=["Type [[y=-5x^2+20x]].","Tap the vertex: $(2,\\,20)$.","The maximum height is $20$ meters."]
S['AM-062']=["Type [[y=-4.9x^2+14.7x+2]].","Tap the positive $x$-intercept: $(3.13,\\,0)$.","Of the options, $3.1$ is the closest."]
S['AM-064']=["Type [[f(x)=2x^2-5x+3]].","Type [[f(4)]]: it returns $15$.","So $f(4)=15$."]
S['AM-066']=["Type [[y=(x-3)^2-7]] and [[y=x^2]].","Tap the vertex of each: $(3,\\,-7)$ and $(0,\\,0)$.","The vertex moved $3$ to the right and $7$ down."]
S['AM-067']=["Put $x=5$ into the equation: $25-5k+20=0$. Let $x$ stand for $k$: type [[y=25-5x+20]] and [[y=0]].","Tap the intersection: $(9,\\,0)$.","So $k=9$."]
S['AM-071']=["Two widths plus the length use $80$ meters, so the length is $80-2x$. Type [[y=x(80-2x)]].","Type each option and hide the others in turn: [[y=80x-2x^2]] is drawn exactly on top of it.","Only that option gives the same graph as the area $x(80-2x)$."]
S['AM-073']=["Type [[y=-3x^2+150x]].","Tap the vertex: $(25,\\,3750)$.","The revenue is greatest at the price $x=25$."]
S['AM-074']=["Type [[y=x^2-12x+c]] (slider $c$).","Slide $c$ until the parabola just touches the $x$-axis at one point.","That happens at $c=36$, where the vertex is $(6,\\,0)$."]
S['AM-079']=["Type [[y=-5*3^x+7]].","Tap the point where the curve crosses the $y$-axis: $(0,\\,2)$.","The $y$-intercept is $(0,2)$."]
S['AM-084']=["Type [[y=(12-x)/(2+x)]] and zoom out to the right.","The curve flattens along a horizontal line. Type [[y=-1]] to confirm it hugs that line.","As $x$ increases without bound, $f(x)$ approaches $-1$."]
S['AM-086']=["Choose $p=1$ and $q=2$: type [[y=(x-1)^2(x+1)(x-2)]].","Tap the $x$-intercepts: $-1$, $1$ and $2$.","The graph has $3$ distinct $x$-intercepts (the repeated factor adds no new intercept)."]
S['AM-092']=["Direct proportion means $x=ky^2$. Type [[6/8]]: it returns $k=0.75$.","Type [[15/0.75]]: it returns $20$.","So $y^2=20$ when $x=15$."]
S['AM-101']=["From $N(0)=100$ we get $k=100$. Type [[y=100*2^(-a*x)]] (slider $a$).","Plot the points [[(1,25)]] and [[(2,6.25)]].","Slide $a$ until the curve passes through both points: $a=2$."]
S['AM-108']=["Type all four parabolas, one per line.","Tap each vertex: $(-2,\\,-3)$, $(3,\\,-1)$, $(-3,\\,-1)$, $(-1,\\,2)$.","The second quadrant has $x<0$ and $y>0$: only $(-1,\\,2)$ fits."]
S['AM-116']=["Type [[y=2x^2+12x+11]].","Tap the vertex: $(-3,\\,-7)$.","The vertex is $(-3,\\,-7)$."]
S['AM-124']=["Type [[f(x)=2x-3]] and [[g(x)=x^2+1]], then [[y=g(f(x))]].","Type each option as its own line: [[y=4x^2-12x+10]] lies exactly on top of the composite.","Only that expression gives the same graph."]
S['AM-125']=["Type [[f(x)=3x+k]]: $f(2)=6+k$, and $f(f(2))=3(6+k)+k=18+4k$.","Type [[y=18+4x]] and [[y=38]] (letting $x$ stand for $k$).","Tap the intersection: $(5,\\,38)$, so $k=5$."]
S['AM-126']=["It is undefined where $(x-2)^2-9=0$. Type [[y=(x-2)^2-9]].","Tap the zeros: $x=-1$ and $x=5$.","So $g$ is undefined at $x=-1$ and $x=5$."]
S['AM-132']=["Type [[y=a(x+4)(x-10)]] (slider $a$).","Slide $a$ until the lowest point has $y=-98$: $a=2$.","Type [[2*4*(-10)]]: it returns $f(0)=-80$."]
S['AM-138']=["From $(0,10)$: $1+b=10$, so $b=9$. Type [[y=a^x+9]] (slider $a$) and plot [[(2,13)]].","Slide $a$ until the curve passes through the point: $a=2$.","Type [[2*9]]: it returns $ab=18$."]
S['AM-140']=["Type [[y=2(x-4)^2-32]].","Tap the two $x$-intercepts: $(0,\\,0)$ and $(8,\\,0)$.","So $t=8$."]
S['AM-144']=["Type [[y=x(320-10x)]] and the line [[y=2400]].","Tap the two grey dots: $(12,\\,2400)$ and $(20,\\,2400)$.","Only $20$ appears among the options."]
S['AM-146']=["Type [[y=(2x-4)/((x+11)(x-6))]].","Tap the $x$-intercept: $(2,\\,0)$, so $g(2)=0$ and $a+5=2$.","Type [[2-5]]: it returns $a=-3$."]
S['AM-147']=["The expression is undefined when $x-5c=0$. Type [[y=x-5c]] (slider $c$).","Slide $c$ until the line crosses the $x$-axis at $x=10$: $c=2$.","Type [[10-5*2]]: it returns $0$, confirming $c=2$."]
S['AM-150']=["Try an example with $a>0$ and $c<0$: type [[y=x^2+x-6]].","Tap the intercepts $(-3,\\,0)$ and $(2,\\,0)$ and the vertex $(-0.5,\\,-6.25)$.","Statements I and II hold (and the product of zeros is $\\dfrac ca<0$ for every such $f$); here the vertex is in the third quadrant, so III does not have to hold."]
S['AM-151']=["At $x=3$: $258=2+2^8$, so $c=3$. Type [[2^(3*3-1)]]: it returns $256$, leaving $\\dfrac{9+a}{3b}=2$, i.e. $9+a=6b$.","At $x=-12$ the term $2^{-37}$ is almost $0$. Type [[2^(-37)]] to see it, so $\\dfrac{144+a}{-12b}=-\\dfrac{17}{4}$, i.e. $144+a=51b$.","Type [[y=6x-9]] and [[y=51x-144]] (letting $x$ stand for $b$). Tap the intersection: $(3,\\,9)$, so $b=3$ and $a=9$.","Check $x=-9$: type [[(81+9)/(-27)]]; it returns $-3.333$, which is $-\\dfrac{10}{3}$. Then type [[9*3*3]]: it returns $81$."]
S['AM-152']=["Type [[y=5*3^(x+2)]] and tap the $y$-intercept: $(0,\\,45)$.","Type [[y=45*3^x]]: it lies exactly on the graph, and the coefficient $45$ is the intercept.","Type [[y=15*3^(x+1)]]: it also lies on the graph, but its coefficient is $15$, not $45$.","Only the first form displays the intercept."]
S['AM-153']=["Type [[y=96*2^(x-3)]] and tap the $y$-intercept: $(0,\\,12)$.","Type [[y=48*2^(x-2)]]: same graph, but its coefficient is $48$, not $12$.","Type [[y=12*2^x]]: same graph, and the coefficient $12$ is the intercept.","Only the second form displays the intercept."]
S['AM-154']=["Type [[y=3*4^(x+2)\\{x>=0\\}]] and tap the lowest point, at $x=0$: $(0,\\,48)$.","Type [[y=48*4^x]]: same graph, and the coefficient $48$ is the minimum.","Type [[y=48*2^(2x)]]: same graph again, with coefficient $48$.","Both forms display the minimum."]
S['AM-155']=["Type [[y=6*2^(x+3)\\{x>=0\\}]] and tap the lowest point, at $x=0$: $(0,\\,48)$.","Type [[y=12*2^(x+2)]]: same graph, but its coefficient is $12$, not $48$.","Type [[y=24*2^(x+1)]]: same graph, but its coefficient is $24$, not $48$.","Neither form displays the minimum."]
S['AM-156']=["Type [[f(x)=200*1.5^(x/2)]].","Type [[f(4)/f(0)]]: it returns $2.25$, the growth factor for every increase of $4$.","Type [[(2.25-1)*100]]: it returns $125$."]
S['AM-157']=["Type [[f(t)=2400*0.8^(t/5)]].","Type [[f(10)/f(0)]]: it returns $0.64$, the factor for every increase of $10$.","Type [[(1-0.64)*100]]: it returns $36$, so the value decreases by $36\\%$."]
S['AM-158']=["$m$ minutes is $\\dfrac m{60}$ hours, so $N=500\\cdot2^{\\frac{m}{60}/3}$. Type [[N(t)=500*2^(t/3)]].","Test $m=180$ minutes (3 hours): type [[N(3)]]; it returns $1000$.","Type [[500*2^(180/180)]]: it returns $1000$, a match. Type [[500*2^(180/20)]]: it returns $256000$, so the $\\dfrac m{20}$ form fails.","The exponent must be $\\dfrac m{180}$."]
S['AM-159']=["Type [[y=12000*0.85^x\\{0<=x<=6\\}]].","Tap the $y$-intercept: $(0,\\,12000)$. The input $x=0$ is the start of $2018$.","So $12{,}000$ is the estimated number of visitors in $2018$."]
S['AM-161']=["Type [[y=50*3^(x/4)]] and the line [[y=1350]].","Tap the intersection: $(12,\\,1350)$.","The population reaches $1{,}350$ after $12$ years."]
